{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table prd_db.justherbs.justherbs_ad_creatives_fact_items as with video_metrics as ( select ad_id::string as ad_id, date_start::date Date, sum(f.value:value::int) as total_3_sec_views from datalake_db.justherbs.just_herbs_facebook_customad_video_metrics_data, lateral flatten(input => actions) f where f.value:action_type::string = \'video_view\' group by 1,2 ), thruplay_metrics AS ( SELECT ad_id::STRING AS ad_id, date_start::date Date, SUM(f.value:value::INT) AS total_thruplays FROM datalake_db.justherbs.just_herbs_facebook_customad_video_metrics_data, LATERAL FLATTEN(input => video_thruplay_watched_actions) f GROUP BY 1,2 ), landing_page_views as ( select concat(\'HTTPS://WWW.JUSTHERBS.IN\', upper(landingpage)) as landingpage, date, sum(cast(sessions as int)) as sessions, sum(cast(engagedsessions as int)) as engaged_sessions, sum(cast(addtocarts as int)) as add_to_carts from prd_db.justherbs.ga4_justherbs_landing_page_funnel_metrics group by 1,2 ), marketing_data as ( select cast(cast(ad_id as int) as string) ad_id, upper(adset_name) as adset_name, upper(campaign_name) as campaign_name, regexp_replace(ad_name, \' +\', \' \') as ad_name, date, sum(SPEND) as amount_spend, sum(impressions) as impressions, sum(clicks) as clicks, sum(Add_to_carts) as atc, sum(reach) as reach, sum(link_clicks) as link_clicks from prd_db.justherbs.dwh_jh_MARKETING_CONSOLIDATED group by 1,2,3,4,5 ), shopify_sales as ( SELECT final_utm_content AS ad_id, landingpageurl AS landing_page_url, sku, product_name, DATE(order_timestamp) AS order_date, SUM(weighted_order_count) AS total_orders, SUM(IFNULL(line_item_sales,0)) - sum(ifnull(discount,0)) AS total_sales FROM ( SELECT *, 1 / COUNT(*) OVER (PARTITION BY order_name) AS weighted_order_count FROM prd_db.justherbs.dwh_SHOPIFY_FACT_ITEMS ) GROUP BY 1,2,3,4,5 ), joined_data AS ( SELECT COALESCE(m.ad_id, s.ad_id, v.ad_id) AS ad_id, COALESCE(m.date, s.order_date, v.date) AS date, m.ad_name, m.adset_name, m.campaign_name, s.landing_page_url, s.sku, s.product_name, NVL(m.amount_spend, 0) AS raw_spend, NVL(m.impressions, 0) AS raw_impressions, NVL(m.clicks, 0) AS raw_clicks, NVL(m.link_clicks, 0) AS raw_link_clicks, NVL(m.reach, 0) AS raw_reach, NVL(m.atc, 0) AS raw_atc, NVL(v.total_3_sec_views, 0) AS raw_video_views, NVL(t.total_thruplays, 0) AS total_thruplays, NVL(s.total_orders, 0) AS total_orders, NVL(s.total_sales, 0) AS total_sales, NULLIF(COUNT(*) OVER (PARTITION BY COALESCE(m.ad_id, s.ad_id, v.ad_id), COALESCE(m.date, s.order_date)), 0) AS ad_divisor, NULLIF(COUNT(*) OVER (PARTITION BY s.landing_page_url, COALESCE(m.date, s.order_date)), 0) AS lp_divisor FROM marketing_data m FULL OUTER JOIN shopify_sales s ON m.ad_id = s.ad_id AND m.date = s.order_date LEFT JOIN video_metrics v ON v.ad_id = COALESCE(m.ad_id, s.ad_id) AND v.date = COALESCE(m.date, s.order_date) LEFT JOIN thruplay_metrics t ON t.ad_id = COALESCE(m.ad_id, s.ad_id) AND t.date = COALESCE(m.date, s.order_date) ) SELECT j.date, j.ad_id, j.ad_name, j.adset_name, j.campaign_name, j.landing_page_url, j.sku, j.product_name, (j.raw_spend / j.ad_divisor) AS amount_spend, (j.raw_impressions / j.ad_divisor) AS impressions, (j.raw_clicks / j.ad_divisor) AS clicks, (j.raw_link_clicks / j.ad_divisor) AS link_clicks, (j.raw_reach / j.ad_divisor) AS reach, (j.raw_atc / j.ad_divisor) AS atc, (j.raw_video_views / j.ad_divisor) AS total_3_sec_views, (j.total_thruplays / j.ad_divisor) AS total_thruplays, j.total_orders, j.total_sales, (NVL(l.engaged_sessions, 0) / j.lp_divisor) AS engaged_sessions, (NVL(l.sessions, 0) / j.lp_divisor) AS sessions, (NVL(l.add_to_carts, 0) / j.lp_divisor) AS add_to_carts FROM joined_data j LEFT JOIN landing_page_views l ON LOWER(l.landingpage) = LOWER(j.landing_page_url) AND l.date = j.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from PRD_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            